UPDATE makeup_exam_session
exam_date = #{examDate}, exam_start_time = #{examStartTime}, exam_end_time = #{examEndTime}, location = #{location}, max_capacity = #{maxCapacity},
WHERE id = #{id}

mapper.select:
SELECT sess.id, sess.course_id, c.course_name, c.course_code,
       sess.semester_id, sem.name AS semesterName,
       sess.exam_date, sess.exam_start_time, sess.exam_end_time,
       sess.location, sess.max_capacity, sess.enrolled_count,
       sess.status, sess.create_time
FROM makeup_exam_session sess
JOIN course c ON sess.course_id = c.id
JOIN semester sem ON sess.semester_id = sem.id

    AND sess.course_id = #{courseId}
    AND sess.semester_id = #{semesterId}
    AND sess.status = #{status}
    AND sess.exam_date = #{examDate}

ORDER BY sess.exam_date DESC, sess.exam_start_time ASC

SELECT sess.id, c.course_name, sess.exam_date, sess.exam_start_time, sess.exam_end_time, sess.location
FROM makeup_exam_session sess
JOIN course c ON sess.course_id = c.id
WHERE sess.location = #{location}
  AND sess.exam_date = #{examDate}
  AND sess.status NOT IN ('已取消', '已结束')
  AND sess.id != #{excludeId}
  AND (sess.exam_start_time < #{examEndTime} AND sess.exam_end_time > #{examStartTime})
